# derive 3s where collinear between any two marker points for direction eight
marks=[(r,c) for r,row in enumerate(demo_in) for c,v in enumerate(row) if v==5]
three=[(r,c) for r,row in enumerate(demo_out) for c,v in enumerate(row) if v==3]
def on_segment(p,a,b):
 r,c=p; ra,ca=a; rb,cb=b
 return (r-ra)*(cb-ca)==(c-ca)*(rb-ra) and min(ra,rb)<=r<=max(ra,rb) and min(ca,cb)<=c<=max(ca,cb)
seg={p for p in [(r,c) for r in range(13) for c in range(12)] if any(on_segment(p,a,b) for i,a in enumerate(marks) for b in marks[i+1:] if a!=b)}
print('3 not line between any markers', [p for p in three if p not in seg][:40],len([p for p in three if p not in seg]))
print('line candidate missing', [p for p in seg if demo_in[p[0]][p[1]]==4 and demo_out[p[0]][p[1]]!=3][:40],len([p for p in seg if demo_in[p[0]][p[1]]==4 and demo_out[p[0]][p[1]]!=3]))

import math,collections
for p in three:
 dirs=set()
 for i,a in enumerate(marks):
  for b in marks[i+1:]:
   if on_segment(p,a,b):
    dr=b[0]-a[0]; dc=b[1]-a[1]; g=math.gcd(abs(dr),abs(dc)); dirs.add((dr//g,dc//g))
 print(p, sorted(dirs)[:8])

demo_out[4][0]=3
# candidates from aligned 8-direction marker pairs, strict between
aligned=set()
for i,a in enumerate(marks):
 for b in marks[i+1:]:
  dr=b[0]-a[0];dc=b[1]-a[1]
  if dr==0 or dc==0 or abs(dr)==abs(dc):
   g=math.gcd(abs(dr),abs(dc))
   sr,sc=dr//g,dc//g
   for k in range(1,g): aligned.add((a[0]+k*sr,a[1]+k*sc))
print('output3 not aligned',set(three)-aligned)
print('aligned non3',sorted(p for p in aligned if demo_in[p[0]][p[1]]==4 and demo_out[p[0]][p[1]]!=3))
print('counts',len(three),len(aligned))

for p in sorted(p for p in aligned if demo_out[p[0]][p[1]]!=3):
 a_pairs=[]
 for i,a in enumerate(marks):
  for b in marks[i+1:]:
   dr=b[0]-a[0];dc=b[1]-a[1]
   if (dr==0 or dc==0 or abs(dr)==abs(dc)) and on_segment(p,a,b) and p not in [a,b]: a_pairs.append((a,b))
 print(p,a_pairs[:4])

# segments in rows & columns only
hv=set()
for r,row in enumerate(demo_in):
 xs=[c for c,v in enumerate(row) if v==5]
 for a,b in zip(xs,xs[1:]): hv.update((r,c) for c in range(a+1,b))
for c in range(12):
 ys=[r for r in range(13) if demo_in[r][c]==5]
 for a,b in zip(ys,ys[1:]): hv.update((r,c) for r in range(a+1,b))
print('3 not hv',set(three)-hv)
print('hv non3',sorted(p for p in hv if demo_out[p[0]][p[1]]!=3))
